```jsx
function ContactList({ contacts, query }) {
  const visibleContacts = contacts.filter(contact =>
    contact.name.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <ul>
      {visibleContacts.map(contact => (
        <ContactRow key={contact.id} contact={contact} />
      ))}
    </ul>
  );
}
```
The key sits on ContactRow, the element directly produced by this map, and stays tied to the same contact through filtering or sorting.

```jsx
function EditableContacts({ contacts }) {
  const sorted = [...contacts].sort((a, b) => a.name.localeCompare(b.name));

  return (
    <ul>
      {sorted.map(contact => (
        <EditableContact key={contact.id} contact={contact} />
      ))}
    </ul>
  );
}
```
Copying before sort avoids mutating the input array, and the ID preserves each contact's component identity through the new order.

```jsx
function ContactPage({ selectedContact }) {
  return (
    <EditContact
      key={selectedContact.id}
      contact={selectedContact}
    />
  );
}

function EditContact({ contact }) {
  const [name, setName] = useState(contact.name);
  return <input value={name} onChange={event => setName(event.target.value)} />;
}
```
A new contact ID creates a new editing session. If drafts must survive switching, this reset strategy should not be used.

```jsx
import { Fragment } from 'react';

function Glossary({ entries }) {
  return (
    <dl>
      {entries.map(entry => (
        <Fragment key={entry.id}>
          <dt>{entry.term}</dt>
          <dd>{entry.definition}</dd>
        </Fragment>
      ))}
    </dl>
  );
}
```
Each glossary record owns two DOM siblings, while the keyed Fragment provides one React identity without inserting a wrapper.
